        ('hiv_plhiv_virologically_suppressed', 'metric', 'PLHIV virologically suppressed', 'People living with HIV virologically suppressed on their most recent viral load.', 'Distinct patients from the VL-tested cohort whose most recent viral load in the 12-month window is numerically below 1000 copies/mL', null, 'tamanu', 'MSF', null, 'MSF OCA Standard Indicators Report (HIV/TB/PMTCT) operational definition', 'count', 'patient', 'facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__hivtb_standard_indicators.md'),
        ('htn_bp_controlled', 'metric', 'Hypertension patients with controlled BP', 'Hypertension patients with a controlled blood-pressure measurement in the reporting month.', 'Distinct hypertension patients with a controlled blood-pressure measurement in the reporting month', null, 'tamanu', 'MSF', null, 'MSF NCD program operational definition', 'count', 'patient', 'age_group,sex,facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/ncd-indicators.md'),
        ('htn_bp_measured', 'metric', 'Hypertension patients with BP measured', 'Hypertension patients with at least one blood-pressure measurement in the reporting month.', 'Distinct hypertension patients with at least one recorded blood-pressure measurement in the reporting month', null, 'tamanu', 'MSF', null, 'MSF NCD program operational definition', 'count', 'patient', 'age_group,sex,facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/ncd-indicators.md'),
        ('hypertension_followup', 'metric', 'MSF Kule OPD — Hypertension — follow-up consultations', 'MSF Kule chronic-care OPD report: follow-up outpatient consultations for Hypertension, weekly by sex and age band.', 'NCD-area follow-up consultations whose visit-form primary diagnosis (kulencdvisit002) maps to Hypertension.', null, 'tamanu', 'MSF', null, 'MSF Kule chronic-care OPD consultations report operational definition', 'count', 'encounter', 'age_group,sex,facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__opd_indicators.md'),
        ('medication_side_effects', 'metric', 'Patients with medication side effects', 'Distinct patients with a documented medication side effect on a Psychiatry Follow Up form in the reporting month.', 'Distinct patients with a non-empty answer to any of the three side-effect questions (extra-pyramidal/metabolic/other) on a Psychiatry Follow Up form in the reporting month', null, 'tamanu', 'MSF', null, 'MSF Mental Health Sessions (Psychiatry and mhGAP) program operational definition', 'count', 'patient', 'facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__mental_health_sessions.md'),
        ('opd_visit', 'metric', 'OPD visits', 'Outpatient department visits. One row per visit, from encounters whose first recorded segment is a clinic, vaccination or imaging phase.', 'Encounters whose first recorded segment carries OMOP visit concept 9202 (Outpatient Visit), counted on the visit date', null, 'tamanu', 'AIHW', '400604', 'Visit concept follows the AIHW METeOR object class "Non-admitted patient service event" (METeOR 400604), the closest AIHW concept anchor for a non-admitted clinic/vaccination/imaging encounter. AIHW registers no plain OPD attendance-count indicator -- its non-admitted reporting is built around the Tier 2 Non-Admitted Services Classification and per-clinic activity counts, not a single cross-clinic count -- so this is a BES composition over the AIHW concept, not an implementation of an AIHW indicator. "Occasion of service" (METeOR 270511) was considered and rejected as the anchor: it is scoped to a narrower residual clinic category, not the general OPD population this metric covers. Pending alignment with the deploying country''s national HMIS definition.', 'count', 'visit', 'facility_id,location_id,sex', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__outpatient_visit.md'),
        ('other_chronic_followup', 'metric', 'MSF Kule OPD — Other chronic diseases — follow-up consultations', 'MSF Kule chronic-care OPD report: follow-up outpatient consultations for Other chronic diseases, weekly by sex and age band.', 'NCD-area follow-up consultations whose visit-form primary diagnosis (kulencdvisit002) maps to Other chronic diseases.', null, 'tamanu', 'MSF', null, 'MSF Kule chronic-care OPD consultations report operational definition', 'count', 'encounter', 'age_group,sex,facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__opd_indicators.md'),
        ('patients_active', 'metric', 'Active NCD patients', 'Patients with an active NCD registration as of the reporting month.', 'Distinct patients with an active NCD registration as of month end (active before month end and exit not yet recorded)', null, 'tamanu', 'MSF', null, 'MSF NCD program operational definition', 'count', 'patient', 'age_group,sex,facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/ncd-indicators.md'),
        ('patients_new', 'metric', 'Newly enrolled NCD patients', 'Patients whose NCD registration first transitioned to ncdactive during the reporting month and were still active at month end.', 'Distinct patients whose NCD registration first became active in the reporting month and who were still active at month end', null, 'tamanu', 'MSF', null, 'MSF NCD program operational definition', 'count', 'patient', 'age_group,sex,facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/ncd-indicators.md'),
        ('pmtct_hiv_exposed_babies_born_alive', 'metric', 'HIV-exposed babies born alive', 'HIV-exposed infants born alive to mothers who delivered in an MSF facility.', 'Distinct exposed-child patients with an Exposed Child initial-visit form in the reporting month whose mother (via mother_id) delivered in an MSF facility, with the initial visit within 12 weeks of that delivery', null, 'tamanu', 'MSF', null, 'MSF OCA Standard Indicators Report (HIV/TB/PMTCT) operational definition', 'count', 'patient', 'facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__hivtb_standard_indicators.md'),
        ('pmtct_hiv_exposed_newborns_pep_72h', 'metric', 'HIV-exposed newborns started on PEP within 72h', 'HIV-exposed newborns who started post-exposure prophylaxis within 72 hours of birth.', 'Distinct exposed-child patients with an initial-visit form in the reporting month recording PEP started within 72h, whose mother (via mother_id) delivered in an MSF facility', null, 'tamanu', 'MSF', null, 'MSF OCA Standard Indicators Report (HIV/TB/PMTCT) operational definition', 'count', 'patient', 'facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__hivtb_standard_indicators.md'),
        ('pmtct_hiv_exposed_pcr_dna_done', 'metric', 'HIV-exposed infants with initial DNA PCR done', 'HIV-exposed infants with an initial DNA PCR test performed.', 'Distinct exposed infants with a published initial DNA PCR lab result in the reporting month whose mother (via mother_id) delivered in an MSF facility', null, 'tamanu', 'MSF', null, 'MSF OCA Standard Indicators Report (HIV/TB/PMTCT) operational definition', 'count', 'patient', 'facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__hivtb_standard_indicators.md'),
        ('pmtct_hiv_positive_delivering', 'metric', 'HIV+ women delivering in an MSF facility', 'HIV-positive women who delivered in an MSF facility during the reporting month.', 'Distinct women with a PMTCT Delivery form marked delivery-in-MSF-facility = Yes, bucketed by the recorded delivery date falling in the reporting month', null, 'tamanu', 'MSF', null, 'MSF OCA Standard Indicators Report (HIV/TB/PMTCT) operational definition', 'count', 'patient', 'facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__hivtb_standard_indicators.md'),
        ('pmtct_hiv_positive_delivering_on_art', 'metric', 'HIV+ women delivering on ART', 'HIV-positive women delivering in an MSF facility who were on ART.', 'Distinct women from the delivering-in-MSF cohort who were already on ART at ANC enrolment, or initiated ART at an ANC visit before the delivery date', null, 'tamanu', 'MSF', null, 'MSF OCA Standard Indicators Report (HIV/TB/PMTCT) operational definition', 'count', 'patient', 'facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__hivtb_standard_indicators.md'),
        ('program_registry_enrolment', 'metric', 'Program registry enrolments', 'Patient enrolments in a Tamanu program registry. One row per enrolment, spanning registration to the end of the registration, disaggregated by registry and by the patient''s clinical status within it.', 'Patient program registrations, excluding those recorded in error, counted at the registration datetime. The row is a span, so a consumer may instead count enrolments open during a period -- period_start before its end and period_end null or after its start -- which is a different number over the same rows', null, 'tamanu', 'BES', null, 'A program registry is Tamanu''s own construct for following a patient through a long-running care programme, so the enrolment is defined by the deployment''s registry configuration rather than by an external standard. The measure is registry-agnostic on purpose: the same definition serves an HIV cascade, a TB register and an NCD register, because the programme-specific part is the clinical status list, which is a disaggregation rather than a definition. Cascade positions and retention are both derived by the consumer -- position by grouping on clinical_status_code, retention from the enrolment boundaries -- so a programme does not need its own metric to be reportable. Where a standards body defines a programme indicator over the same population (WHO HIV treatment coverage, an MSF standard indicator), that indicator is registered separately and this metric is not a substitute for it.', 'count', 'episode', 'registry_code,clinical_status_code,registration_status,currently_at_type,currently_at_id,episode_end_source,facility_id,sex', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__program_registry_enrolment.md'),
